                                        "get_all_calendars",
                                    ],
                                )
                            },
                        )
                    ],
                ),
                # Milestone 1 – The returned calendar data contains the correct medical event at 15:00
                Milestone(
                    snapshot_constraints=[
                        SnapshotConstraint(
